#include <type_traits>
template<typename T, typename = std::enable_if_t<std::is_floating_point<T>::value>>
T compute_inverse(T value) {
    return 1 / value;
}
int main() {
    double d = 2.0;
    auto result = compute_inverse(d); // Valid: double is floating point
    // int i = 2; // Uncommenting this line would cause a compile-time error
    // auto invalid_result = compute_inverse(i);
    return 0;
}
